#!/usr/bin/env python3
"""Regenerates src/desktop/theme/Icon.slint from data/icons/*.svg.

Slint resolves `@image-url` at compile time, so the component lists every icon literally; the
UI targets embed the files. Run after adding or removing an icon; --check fails when the
component is out of date (CI).
"""
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
TARGET = ROOT / "src/desktop/theme/Icon.slint"


def render() -> str:
    names = sorted(path.stem for path in (ROOT / "data/icons").glob("*.svg"))
    lines = [
        "// Generated by scripts/gen-ui-icons.py from data/icons; do not edit.",
        "",
        "// A LunaDash interface icon by name, tinted with `color`: "
        + ", ".join(names) + ".",
        "export component Icon inherits Image {",
        "    in property <string> name;",
        "    in property <color> color: #f1f1f5;",
        "    colorize: root.color;",
        "    image-fit: contain;",
        "    width: 18px;",
        "    height: 18px;",
        "    accessible-role: none;",
        "    source:",
    ]
    lines += [f'        root.name == "{n}" ? @image-url("../../../data/icons/{n}.svg") :'
              for n in names]
    lines += ['        @image-url("../../../data/icons/file.svg");', "}"]
    return "\n".join(lines) + "\n"


def main() -> None:
    text = render()
    if "--check" in sys.argv:
        if not TARGET.is_file() or TARGET.read_text() != text:
            sys.exit("src/desktop/theme/Icon.slint is out of date: run scripts/gen-ui-icons.py")
        return
    TARGET.write_text(text)
    print(f"wrote {TARGET.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
